import{_ as t,o as r,c as s,a2 as n}from"./chunks/framework.CqdVOxXJ.js";const e="/rakkii-cars-guide/screenshots/10-workshop-operations-board-calendar-backjobs-contractors/03-dashboard.png",a="/rakkii-cars-guide/screenshots/10-workshop-operations-board-calendar-backjobs-contractors/01-shop-board.png",i="/rakkii-cars-guide/screenshots/10-workshop-operations-board-calendar-backjobs-contractors/02-contractor-monitor.png",m=JSON.parse('{"title":"10. Workshop operations: board, calendar, customers, backjobs & contractors","description":"","frontmatter":{},"headers":[],"relativePath":"chapters/10-workshop-operations-board-calendar-backjobs-contractors.md","filePath":"chapters/10-workshop-operations-board-calendar-backjobs-contractors.md","lastUpdated":1793268728000}'),g={name:"chapters/10-workshop-operations-board-calendar-backjobs-contractors.md"};function d(l,o,c,h,p,b){return r(),s("div",null,[...o[0]||(o[0]=[n('<h1 id="_10-workshop-operations-board-calendar-customers-backjobs-contractors" tabindex="-1">10. Workshop operations: board, calendar, customers, backjobs &amp; contractors <a class="header-anchor" href="#_10-workshop-operations-board-calendar-customers-backjobs-contractors" aria-label="Permalink to &quot;10. Workshop operations: board, calendar, customers, backjobs &amp; contractors&quot;">​</a></h1><p><strong>For:</strong> Shop Owner · <strong>Hub:</strong> Workshop</p><p>The pages in this chapter help you run the floor across all jobs at once instead of one job at a time.</p><h2 id="_10-1-shop-board-workshop-board" tabindex="-1">10.1 Shop board (<code>/workshop/board</code>) <a class="header-anchor" href="#_10-1-shop-board-workshop-board" aria-label="Permalink to &quot;10.1 Shop board (`/workshop/board`)&quot;">​</a></h2><p>The Kanban view of every car in play. Each card shows the plate, a subtitle (type, category), the customer, checklist progress, promised date and any amount the customer still owes.</p><table tabindex="0"><thead><tr><th>Lane</th><th>Statuses in it</th></tr></thead><tbody><tr><td><strong>New</strong></td><td>New inquiry, Booked</td></tr><tr><td><strong>Quote / LOA</strong></td><td>For canvass, Quoted, Waiting for LOA, Authorized</td></tr><tr><td><strong>Under repair</strong></td><td>Under repair</td></tr><tr><td><strong>Parts &amp; QC</strong></td><td>Waiting for parts, Quality check</td></tr><tr><td><strong>On hold</strong></td><td>On hold</td></tr><tr><td><strong>Ready</strong></td><td>Ready for pickup (in play for 90 days)</td></tr></tbody></table><p><strong>Filters</strong></p><ul><li>Scope: <strong>Mine</strong>, <strong>All open</strong>, <strong>All</strong>.</li><li>Type: <strong>Retail</strong>, <strong>Insurance</strong>, <strong>Fleet</strong>.</li><li><strong>Lane</strong> (or <strong>All lanes</strong>).</li><li><strong>Target date</strong>: <strong>Any date</strong>, <strong>Due today</strong>, <strong>Overdue</strong>.</li><li><strong>Stuck</strong>: <strong>Any</strong>, <strong>Waiting LOA</strong>, <strong>Waiting parts</strong>, <strong>Unpaid</strong>.</li><li><strong>Work category</strong>.</li></ul><p>Switch between <strong>Columns</strong> (Kanban) and <strong>List</strong> (sortable table: Plate, Customer, Lane, Status, Type, Category, Target date, Balance). Jobs that match a search but are off the board (released, closed) show under <strong>Also found (off the board)</strong>.</p><p><strong>Morning routine:</strong> filter <strong>Target date: Due today</strong> and <strong>Overdue</strong>, then <strong>Stuck: Unpaid</strong> on the Ready lane — those cars must not leave until paid.</p><p>The <strong>Dashboard</strong> (<code>/workshop</code>) complements the board with <strong>Priority jobs</strong>, <strong>Announcements</strong>, <strong>Today&#39;s appointments</strong> (Confirmed / In shop / Waiting), <strong>Due today</strong>, <strong>New web &amp; Messenger inquiries</strong> (with <strong>Confirm booking</strong>), <strong>Ready, but customer still owes</strong>, tiles (<strong>Cars in shop</strong>, <strong>On hold</strong>, <strong>Due today</strong>, <strong>Cash in today</strong>, <strong>Overdue invoices</strong>) and counts by status, type and channel.</p><h3 id="priority-jobs" tabindex="-1">Priority jobs <a class="header-anchor" href="#priority-jobs" aria-label="Permalink to &quot;Priority jobs&quot;">​</a></h3><p>The owner ranks the jobs the shop must finish first. On the Dashboard, <strong>Priority jobs</strong> lists them in order; under <strong>Suggested</strong> the app proposes overdue jobs (plate and target date), and <strong>Add</strong> puts one on the list. You can also make a job a priority from the job itself with <strong>Make priority</strong> and add a short note. Technicians see their priority jobs ranked on <strong>My jobs</strong>.</p><h3 id="find-a-job-fast" tabindex="-1">Find a job fast <a class="header-anchor" href="#find-a-job-fast" aria-label="Permalink to &quot;Find a job fast&quot;">​</a></h3><p>The search box in the top bar (<strong>Plate, job or customer</strong>, shortcut <kbd>/</kbd>) finds any job by plate, job reference or customer name, including released and closed ones.</p><h3 id="customer-activity" tabindex="-1">Customer activity <a class="header-anchor" href="#customer-activity" aria-label="Permalink to &quot;Customer activity&quot;">​</a></h3><p><strong>Workshop › Customer activity</strong> lists what customers did on the website, pay link or portal: web bookings, quote requests, estimates approved or declined, extras approved, payment screenshots and payment notes. The bell in the top bar shows how many are unseen; once anyone at the desk marks an item seen, it leaves the count for everyone. Open an item to go to the job.</p><p><img src="'+e+'" alt="Owner Dashboard with Priority jobs suggestions, Announcements and today&#39;s tiles"></p><p><img src="'+a+'" alt="Shop board columns view with filters"></p><h2 id="_10-2-appointment-target-date-calendar-workshop-calendar" tabindex="-1">10.2 Appointment &amp; target-date calendar (<code>/workshop/calendar</code>) <a class="header-anchor" href="#_10-2-appointment-target-date-calendar-workshop-calendar" aria-label="Permalink to &quot;10.2 Appointment &amp; target-date calendar (`/workshop/calendar`)&quot;">​</a></h2><p>A job has two separate dates:</p><ul><li><strong>Target date</strong> — when the repair should be done.</li><li><strong>Appointment</strong> — when the car is booked to come in (with a time window and a status).</li></ul><ol><li>Open <strong>Workshop › Calendar</strong>. The week is shown; pick a <strong>Day</strong>.</li><li>The selected day lists every job with a target date or an appointment on that day (plate, customer, type and status). A tag says which: <strong>Appointment</strong> or <strong>Target date</strong>.</li><li><strong>No target date or appointment</strong> lists open jobs with neither — give each one a date.</li><li><strong>Book this day</strong> starts a new job with that date.</li></ol><p><strong>Setting the dates on a job:</strong> job <strong>Overview</strong> →</p><ul><li><strong>Target date</strong> → pick the date → <strong>Save target date</strong>.</li><li><strong>Appointment</strong> → <strong>Appointment date</strong>, <strong>Time window</strong> and <strong>Status</strong> (<strong>Confirmed</strong>, <strong>In shop</strong>, <strong>Waiting</strong>) → <strong>Save appointment</strong>. <strong>Clear appointment</strong> removes it.</li></ul><h2 id="_10-3-customers-vehicle-service-history" tabindex="-1">10.3 Customers &amp; vehicle service history <a class="header-anchor" href="#_10-3-customers-vehicle-service-history" aria-label="Permalink to &quot;10.3 Customers &amp; vehicle service history&quot;">​</a></h2><h3 id="customers-workshop-customers" tabindex="-1">Customers (<code>/workshop/customers</code>) <a class="header-anchor" href="#customers-workshop-customers" aria-label="Permalink to &quot;Customers (`/workshop/customers`)&quot;">​</a></h3><p>The list shows each customer with <strong>Cars</strong>, <strong>Last visit</strong>, <strong>Total spent</strong> and <strong>Open jobs</strong>. Use <strong>New customer</strong> or open a row.</p><p>On the customer page (<code>/workshop/customers/:id</code>):</p><ul><li><strong>Customer</strong> details: Name, Mobile, Email, Category (Person, Company, Government), TIN, Credit terms, Billing address, Notes — <strong>Edit</strong> to change.</li><li><strong>Cars</strong> — every vehicle, with last visit; <strong>Add car</strong>.</li><li><strong>Open jobs</strong> and <strong>Service history</strong> (date, plate, work done, amount).</li><li><strong>New job for them</strong> starts a job with the customer filled in.</li></ul><h3 id="vehicles-workshop-vehicles-id" tabindex="-1">Vehicles (<code>/workshop/vehicles/:id</code>) <a class="header-anchor" href="#vehicles-workshop-vehicles-id" aria-label="Permalink to &quot;Vehicles (`/workshop/vehicles/:id`)&quot;">​</a></h3><ul><li><strong>Car</strong> details: Plate (fixed once on file), Make, Model, Year, Color, VIN, Notes.</li><li><strong>Owner</strong>, <strong>Open jobs</strong> and <strong>Service history</strong> for this car across all owners.</li><li><strong>Move to new owner</strong> when a car is sold. The car&#39;s service history stays with the car.</li></ul><h2 id="_10-4-backjob-monitor-workshop-backjobs" tabindex="-1">10.4 Backjob Monitor (<code>/workshop/backjobs</code>) <a class="header-anchor" href="#_10-4-backjob-monitor-workshop-backjobs" aria-label="Permalink to &quot;10.4 Backjob Monitor (`/workshop/backjobs`)&quot;">​</a></h2><p>A backjob is a car that comes back for the same work (a warranty return or comeback).</p><h3 id="log-a-backjob-on-the-original-job" tabindex="-1">Log a backjob on the original job <a class="header-anchor" href="#log-a-backjob-on-the-original-job" aria-label="Permalink to &quot;Log a backjob on the original job&quot;">​</a></h3><ol><li>Open the <strong>original</strong> job (the one being complained about). On <strong>Overview</strong>, card <strong>Backjobs</strong>, press <strong>Log backjob</strong>.</li><li>Fill <strong>Complaint</strong>, <strong>Date returned</strong>, and who is <strong>Responsible</strong> — pick <strong>Staff</strong> (a technician) or <strong>Contractor</strong> (name).</li><li>Tick <strong>Under warranty</strong> if the shop covers it. Add a <strong>Note</strong>.</li><li>Save. Track its <strong>Status</strong>: <strong>Open</strong>, <strong>Fixed</strong> or <strong>Not a backjob</strong>.</li><li><strong>Confirm / change responsible</strong> once the cause is clear.</li><li><strong>Add cost</strong> for every peso spent fixing it: <strong>Category</strong>, <strong>Amount</strong>, <strong>Date</strong>, <strong>Payee</strong> (required for contractor costs), <strong>Note</strong>, <strong>Paid from</strong>. Costs are recorded as shop expenses. <strong>Save warranty note</strong> for the customer-facing warranty remark.</li></ol><p>Backjobs do not change technician pay. They can feed KPI scorecards as a hint (<a href="/rakkii-cars-guide/chapters/11-hr-payroll-kiosk-announcements-documents">Chapter 11</a>).</p><h3 id="the-monitor" tabindex="-1">The monitor <a class="header-anchor" href="#the-monitor" aria-label="Permalink to &quot;The monitor&quot;">​</a></h3><ul><li><strong>By responsible</strong> (this month): <strong>Who</strong>, <strong>Kind</strong> (staff or contractor), number of <strong>Backjobs</strong>, total <strong>Cost</strong>.</li><li><strong>Still open</strong> (any month): <strong>Returned</strong>, <strong>Job</strong>, <strong>Plate</strong>, <strong>Customer</strong>, <strong>Complaint</strong>, <strong>Responsible</strong>, <strong>Warranty</strong>, <strong>Cost</strong>. Items stay until fixed or cleared.</li></ul><h2 id="_10-5-contractor-monitor-workshop-contractors" tabindex="-1">10.5 Contractor Monitor (<code>/workshop/contractors</code>) <a class="header-anchor" href="#_10-5-contractor-monitor-workshop-contractors" aria-label="Permalink to &quot;10.5 Contractor Monitor (`/workshop/contractors`)&quot;">​</a></h2><p>Sublet work (for example upholstery, glass or engine machining) is tracked on the job and monitored here.</p><h3 id="on-the-job-job-order-—-contractors-work-tab" tabindex="-1">On the job: Job Order — Contractors (Work tab) <a class="header-anchor" href="#on-the-job-job-order-—-contractors-work-tab" aria-label="Permalink to &quot;On the job: Job Order — Contractors (Work tab)&quot;">​</a></h3><ol><li>Press <strong>Add contractor</strong>.</li><li>Fill <strong>Contractor</strong>, <strong>Scope</strong> (prefilled from the job&#39;s work category if the shop setting is on), <strong>Status</strong>, <strong>Date start</strong>, <strong>Commitment date</strong>, <strong>Completion date</strong>, <strong>Labour</strong> (agreed amount) and <strong>Note</strong>.</li><li>Save. The line shows days, labour, <strong>Adv. paid</strong> and <strong>Balance</strong>.</li><li>Move it with <strong>Mark ON-GOING</strong> and <strong>Mark COMPLETED</strong>. If the shop requires a contractor signature, completing without one needs an owner/admin reason (<strong>Complete anyway</strong>). Upload a <strong>Signature photo</strong> or type the <strong>Contractor signature</strong> name.</li><li>Pay the contractor with <strong>Adv. paid</strong> (advance) or <strong>Payment</strong>: <strong>Date</strong>, <strong>Paid from</strong>, <strong>Note</strong>. Each payout can be voided.</li><li><strong>Cancel line</strong> if the sublet is called off.</li></ol><p>Statuses: <strong>OPEN</strong>, <strong>ON-GOING</strong>, <strong>COMPLETED</strong>, <strong>CANCELLED</strong>. Technicians see the list read-only.</p><h3 id="the-monitor-1" tabindex="-1">The monitor <a class="header-anchor" href="#the-monitor-1" aria-label="Permalink to &quot;The monitor&quot;">​</a></h3><ul><li>Filters: <strong>Status</strong> (Open and ON-GOING, ON-GOING, COMPLETED, CANCELLED, All), <strong>Contractor</strong>, <strong>Overdue commitment dates only</strong>.</li><li>Columns: <strong>Job</strong>, <strong>Plate</strong>, <strong>Contractor</strong>, <strong>Scope</strong>, <strong>Status</strong>, <strong>Commitment date</strong>, <strong>Days</strong>, <strong>Labour</strong>, <strong>Adv. paid</strong>, <strong>Balance</strong>.</li><li>Badges: <strong>Overdue</strong>, <strong>Due today</strong>, <strong>Soon</strong> (warning days set in <strong>Shop settings › Workshop rules › Contractors</strong>).</li></ul><p><img src="'+i+'" alt="Contractor jobs monitor with overdue filter"></p>',47)])])}const k=t(g,[["render",d]]);export{m as __pageData,k as default};
